mapper.select:
select t.card_name,t.card_name cardName,t.card_month,t.card_month cardMonth,t.card_id,t.card_id
cardId,t.card_price,t.card_price cardPrice,t.status_cd,t.status_cd
statusCd,t.remark,t.community_id,t.community_id communityId,t.create_time createTime,t.pa_id paId,pa.num areaNum
from car_month_card t
left join parking_area pa on t.pa_id = pa.pa_id
where 1 =1

    and t.card_name= #{cardName}


    and t.card_month= #{cardMonth}


    and t.card_id= #{cardId}


    and t.card_price= #{cardPrice}


    and t.status_cd= #{statusCd}


    and t.remark= #{remark}


    and t.community_id= #{communityId}


    and t.pa_id= #{paId}

order by t.create_time desc

    limit #{page}, #{row}

